CREATE TYPE "AttemptStatus" AS ENUM ('PREPARING','GENERATING','COMPLETED','FAILED'); CREATE TABLE "GenerationAttempt" ("id" uuid PRIMARY KEY,"ownerId" uuid NOT NULL REFERENCES "User"("id"),"sessionId" uuid NOT NULL REFERENCES "VisualizationSession"("id"),"status" "AttemptStatus" NOT NULL DEFAULT 'PREPARING',"acceptedAt" timestamptz NOT NULL DEFAULT now(),"deadlineAt" timestamptz NOT NULL,"finishedAt" timestamptz,"safeErrorCode" varchar(80),"revision" integer NOT NULL DEFAULT 0); CREATE INDEX "GenerationAttempt_ownerId_status_idx" ON "GenerationAttempt"("ownerId","status");
